  allPRs: state => Object.values(state.chats || {}).filter(c => c.pr_view?.from_branch),
  isChatUpdating: state => (chatId) => {
    const updatingAt = state.chatEvents[chatId]?.updatingAt
    if (!updatingAt) return false
    return (Date.now() - new Date(updatingAt).getTime()) < 3000
  },
})

